-- Gold layer DDL for stream: outdoor-weather
-- Generated by ndp-gold-ddl

CREATE SCHEMA IF NOT EXISTS gold;

-- Sync mode: Create if not exists
-- CA-SYNC-CHECK: schema=gold name=outdoor_weather_hourly
CREATE MATERIALIZED VIEW gold.outdoor_weather_hourly
WITH (timescaledb.continuous) AS
SELECT
    time_bucket('1 hour', observation_time) AS bucket,
    ndp_id,
    AVG(humidity_pct) AS humidity_pct_mean,
    MIN(humidity_pct) AS humidity_pct_min,
    MAX(humidity_pct) AS humidity_pct_max,
    AVG(feels_like_c) AS feels_like_c_mean,
    MIN(feels_like_c) AS feels_like_c_min,
    MAX(feels_like_c) AS feels_like_c_max,
    AVG(precipitation_mm) AS precipitation_mm_mean,
    MAX(precipitation_mm) AS precipitation_mm_max,
    COUNT(precipitation_mm) AS precipitation_mm_count,
    AVG(temperature_c) AS temperature_c_mean,
    MIN(temperature_c) AS temperature_c_min,
    MAX(temperature_c) AS temperature_c_max,
    AVG(cloud_cover_pct) AS cloud_cover_pct_mean,
    AVG(wind_speed_kmh) AS wind_speed_kmh_mean,
    MAX(wind_speed_kmh) AS wind_speed_kmh_max,
    AVG(visibility_m) AS visibility_m_mean,
    MIN(visibility_m) AS visibility_m_min,
    AVG(pressure_pa) AS pressure_pa_mean,
    COUNT(*) AS sample_count
FROM silver.weather_observations
GROUP BY bucket, ndp_id;

-- Sync mode: Create if not exists
-- CA-SYNC-CHECK: schema=gold name=outdoor_weather_daily
CREATE MATERIALIZED VIEW gold.outdoor_weather_daily
