    COUNT(precipitation_mm) AS precipitation_mm_count,
    AVG(temperature_c) AS temperature_c_mean,
    MIN(temperature_c) AS temperature_c_min,
    MAX(temperature_c) AS temperature_c_max,
    AVG(cloud_cover_pct) AS cloud_cover_pct_mean,
    AVG(wind_speed_kmh) AS wind_speed_kmh_mean,
    MAX(wind_speed_kmh) AS wind_speed_kmh_max,
    AVG(visibility_m) AS visibility_m_mean,
    MIN(visibility_m) AS visibility_m_min,
