-- Refresh policy for gold.outdoor_weather_hourly
SELECT add_continuous_aggregate_policy('gold.outdoor_weather_hourly',
    start_offset => INTERVAL '4 hours',
    end_offset => INTERVAL '15 minutes',
    schedule_interval => INTERVAL '15 minutes',
    if_not_exists => TRUE
);

-- Refresh policy for gold.outdoor_weather_daily
SELECT add_continuous_aggregate_policy('gold.outdoor_weather_daily',
    start_offset => INTERVAL '3 days',
    end_offset => INTERVAL '1 hour',
    schedule_interval => INTERVAL '1 hour',
    if_not_exists => TRUE
